from collections import Counter

def predict_v10(corners, center):
    TL, TR, BL, BR = corners

    if TL == TR == BL == BR and TL != 0:
        if center > TL:
            return center
        return TL

    if (TL == BL and TL != 0) and (TR == BR and TR != 0) and TL != TR:
        return TL

    cnt = Counter(corners)
    if max(cnt.values()) == 3:
        majority = max(cnt.items(), key=lambda x: x[1])[0]
        minority = [c for c in corners if c != majority][0]
        min_pos = [i for i, c in enumerate(corners) if c == minority][0]

        if center == minority:
            return minority
        elif center == majority:
            if min_pos in [0, 1]:
                return majority
            if min_pos == 2:
                return minority
            if min_pos == 3:
                return majority
        else:
            return majority

    left_match = (TL == BL and TL != 0)
    right_match = (TR == BR and TR != 0)

    if right_match and not left_match:
        return TR

    if left_match or right_match:
        if left_match:
            pair_val = TL
            if center == pair_val:
                return pair_val
        if right_match:
            pair_val = TR
            if center == pair_val:
                return pair_val
        if left_match and right_match:
            return TL
        return TL or TR

    nonzero = [c for c in corners if c != 0]
    if len(nonzero) == 0:
        return 0
    return nonzero[0]

